34	/// The total payout per policy is capped at twice its insurance sum.
35	const CAP_MULTIPLE: i64 = 2;
36	
37	pub struct Policy<'a> {
38	    insured: &'a [Item],
39	}
40	
41	impl<'a> Policy<'a> {
42	    pub fn insuring(items: &'a [Item]) -> Self {
43	        Policy { insured: items }
44	    }
45	
46	    /// The most the office will ever pay out on this policy.
47	    fn cap(&self) -> i64 {
48	        CAP_MULTIPLE * insurance_sum(self.insured)
49	    }
50	
51	    /// The insured item a reported damage refers to.
52	    fn damaged_item(&self, damage: &Damage) -> Option<&Item> {
53	        self.insured
54	            .iter()
55	            .find(|item| item.item_type == damage.item_type)
56	    }
57	
58	    /// A settlement totals what the office reimburses for each damage the
59	    /// incident reported.
60	    pub fn claim(&self, damages: &[Damage]) -> Settlement {
61	        let reimbursed: f64 = damages
62	            .iter()
63	            .map(|damage| damage_reimbursement(damage, self.damaged_item(damage)))
64	            .sum();
65	        let cap = self.cap();
66	        let payout = round_payout_in_mhpco_favor(reimbursed).min(cap);
67	        Settlement {
68	            payout,
69	            remaining_cap: cap - payout,
70	        }
71	    }
72	}
73	
74	/// A premium is rounded in the MHPCO's favor, which for money the customer
75	/// owes the office means upwards.
76	fn round_premium_in_mhpco_favor(premium: f64) -> i64 {
77	    premium.ceil() as i64
78	}
79	
80	/// A payout is rounded in the MHPCO's favor, which for money the office owes
81	/// the claimant means downwards. Only the settlement total is rounded; the
82	/// reimbursements it sums are carried as fractions.
83	fn round_payout_in_mhpco_favor(payout: f64) -> i64 {
84	    payout.floor() as i64
85	}
86	
87	/// How the MHPCO's two kinds of modifier reach the premium: policy-wide
88	/// modifiers scale the policy base premium, while item-specific modifiers are
89	/// measured against their own item's base premium and are added alongside, so
90	/// a curse never surcharges the rest of the policy.
91	fn premium_before_fee(customer: &Customer, items: &[Item], previous_quotes: usize) -> f64 {
92	    let base = policy_base_premium(items);
93	    base + standing_adjustment(base, customer, previous_quotes) + item_risk_surcharges(items)
94	}
95	
96	pub fn quote(customer: &Customer, items: &[Item], previous_quotes: usize) -> i64 {
97	    let premium = premium_before_fee(customer, items, previous_quotes);
98	    round_premium_in_mhpco_favor(premium) + PROCESSING_FEE
99	}
